a<-commandArgs(TRUE);if(length(a)<3)stop("Usage: km_by_locked_cutoff.R <devpred> <valpred> <out>");if(!requireNamespace("survival",quietly=TRUE)||!requireNamespace("survminer",quietly=TRUE))stop("Install survival and survminer");tr<-read.csv(a[1],check.names=FALSE);va<-read.csv(a[2],check.names=FALSE);out<-a[3];mods<-intersect(setdiff(names(tr),c("ID","Time","Event")),names(va));dir.create(out,recursive=TRUE,showWarnings=FALSE);cuts<-data.frame(model=mods,cutoff=vapply(mods,function(m)median(tr[[m]],na.rm=TRUE),numeric(1)));write.csv(cuts,file.path(out,"development_cutoffs.csv"),row.names=FALSE);for(m in mods){cut<-cuts$cutoff[cuts$model==m];for(nm in c("development","validation")){d<-if(nm=="development")tr else va;d$RiskGroup<-factor(ifelse(d[[m]]>cut,"high","low"),levels=c("high","low"));fit<-survival::survfit(survival::Surv(Time,Event)~RiskGroup,d);p<-survminer::ggsurvplot(fit,d,pval=TRUE,pval.method=TRUE,conf.int=TRUE,risk.table=TRUE,surv.median.line="hv",palette=c("#ED0000FF","#0099B4FF"),ggtheme=ggplot2::theme_classic());pdf(file.path(out,paste0(nm,"_",m,"_km.pdf")),5,5);print(p,newpage=FALSE);dev.off()}}
